def rw(p, f):
    s = open(p, encoding="utf-8").read(); t = f(s); assert t != s, p
    open(p, "w", encoding="utf-8", newline="\n").write(t)
TPL = r"`D:\РАБОЧКА\Шаблон для Кж.dwg`, парақ 3.6 «Узел стыковки арматуры в нахлест и накладка» (сурет: `18_КЖ жүйесі\_суреттер\`)"
ANK = "Анкеровка кестесі (шаблон 3.6): Ø12 = 600 · Ø14 = 700 · Ø16 = 800 · Ø18 = 850 · Ø20 = 950 · Ø22 = 1050 · Ø25 = 1200 · Ø28 = 1300 · Ø32 = 1500 (≈46–50d)."
LAPT = "Шаблон 3.6 нахлёст кестесі (стена, тік және көлденең): Ø12 = 700 (разбежка 300) · Ø14 = 900 (400) · Ø16 = 1000 (500) · Ø18 = 1200 (600); Ø20–Ø32 — нахлёст емес, накладка."
L71 = "71d кестесі (шаблондағы горизонталь узел, разбежка = жартысы): Ø12 = 860 (430) · Ø14 = 1000 (500) · Ø16 = 1140 (570) · Ø18 = 1280 (640) · Ø20 = 1420 (710)."
NAK = "Накладка (Ø ≥ 20, С21-Рн, ГОСТ 14098-2014, L = 10d): Н1 Ø20 L200 0,49 кг · Н2 Ø22 L220 0,66 · Н3 Ø25 L250 0,96 · Н4 Ø28 L280 1,35 · Н5 Ø32 L320 2,01; b = h = 0,5dн; стыктар арасы 600. Көлденең арматура шетінде скоба Ск Ø16 (С23-Рэ): 200 (Ø20), 220 (Ø22), 250 (Ø25), 280 (Ø28), 320 (Ø32; шаблонда «Ø30» деп қате жазылған)."
PRO = "Проём обрамлениесі (шаблон 3.6 «Фрагмент обрамления проема»): проём үстінде хомут ш.100; 200, проёмның екі жағында 200×2 жиі аймақ, шетінен 50."
A3 = "«61-ді негіз көп болады, 56–55 сондай болады… шаблон КЖ файлын ашып қара, нахлёстар, анкеровка қанша екен, сонымен өзің ережеде түзіп ал» → файл ашылды. " + ANK + " Пайдаланушының ауызша «61d / 55–56d» дегені мен шаблон кестесі (46–50d) сәйкес келмейді — әдепкі шаблон кестесі алынды, айырма паспортта сұралады."
A4 = "«Стрелка тек маркада ғана болады. Колоннада, стенада, ригельде болмайды. Ригельде Рм-1 дейді, ол ригельдің бойымен өзі тұрады; стрелка да, жай сызық та болмайды. Стеналарда проём (есік, терезе) болады: отверстиенің дерегі стрелкамен, выноскаға шығарып жазылады — отверстие размері, астына полдан қанша биіктікте тұратыны. Онкологияның схема каркасын қарасаң түсінесің» → Схемада колонна, стена, ригель маркасында стрелка жоқ; ригель маркасы ригель бойымен, выноска сызығынсыз. Стрелкалы выноска — стена проёмына: үстінде проём өлшемі, астында еденнен биіктігі. Үлгі: Онкоцентр схема каркаса (2.x)."
A5 = "«Негізі диаметр жазамыз. Плита, мысалы шаг 200 дейтін болса: бірінші позиция, жақшаның ішінде диаметр (20-лық, болмаса 12-лік), соны жазып, астына шагын жазамыз (200, болмаса 100, 150)» → Позиция выноскасы барлық жерде (жоспарда да): үстінде «поз(ФØ)», мыс. «1(Ф12)»; астында жалпы шаг «ш.200»."
A6 = "«Сен шаблон бойынша жазасың. Колонна, ригель — бұл Онкологиядағы шаблон. Колонна мен ригельге байланысты менің өз ережелерім бар, стена — барлығына байланысты ережем бар. Сол ереженің барлығын қолданасың» → Колонна мен ригель парағы шаблон («Колонна Км-1», «Ригель Рм-1» — Онкоцентрден алынған) бойынша; пайдаланушының колонна, ригель, стена ережелері (`04` кітабы) түгел қолданылады."
A7 = "«Кез келген жерде, барлығында сетка қолданасың. Екеуінің қиылысында» → Колонна–ригель қиылысында әрдайым сетка (сейсмикада да); тұйық хомут қосылмайды."
def f06(s):
    a = "| 2 | Нахлёст 61d ме, 71d ме |"; i = s.index(a); j = s.index("\n", i) + 1
    rows = ("| 2а | Шаблондағы нахлёст/накладка деректері (қосымша, файлдан) | " + LAPT + " " + L71 + " " + NAK + " " + PRO + " Көзі: " + TPL + ". Ескерту: шаблон примечаниесінде «Длина нахлеста 71d» деп жазылған, ал 3.6 кестесі 700/900/1000/1200 — үш нұсқа бар (71d, 61d, шаблон 3.6 кестесі), жоба басында қайсысы екені сұралады | 12.11.2026 | паспорт §2, чек-лист А4 |\n"
            "| 3 | Анкеровка | " + A3 + " | 12.11.2026 | паспорт §2, чек-лист А4, ЕРЕЖЕЛЕР |\n"
            "| 4 | Стрелка | " + A4 + " | 12.11.2026 | чек-лист А13, ЕРЕЖЕЛЕР, memory leader-ticks-rule |\n"
            "| 5 | Позиция выноскасында Ø | " + A5 + " | 12.11.2026 | чек-лист А14, ЕРЕЖЕЛЕР, memory |\n"
            "| 6 | Колонна/ригель парағы: шаблон ба, аналог па | " + A6 + " | 12.11.2026 | чек-лист В1, Д1, ЕРЕЖЕЛЕР |\n"
            "| 7 | Сейсмикада колонна–ригель түйіні | " + A7 + " | 12.11.2026 | чек-лист В7, ЕРЕЖЕЛЕР |\n")
    return s[:j] + rows + s[j:]
rw(os.path.join(OBS, "06_Пайдаланушыға сұрақтар және жауаптар.md"), f06)
def f03(s):
    def rep(prefix, new):
        nonlocal s
        L = s.split("\n"); k = [i for i, l in enumerate(L) if l.startswith(prefix)]; assert k, prefix
        L[k[0]] = new; s = "\n".join(L)
    rep("| А4 |", "| А4 | Нахлёст — паспортта таңдалған кестеден (жоба басында сұралады): **71d** (Ø12 = 860, Ø14 = 1000, Ø16 = 1140, Ø18 = 1280, Ø20 = 1420), **61d** (Ø12 = 730), не **шаблон 3.6 кестесі** (Ø12 = 700, Ø14 = 900, Ø16 = 1000, Ø18 = 1200). Ø ≥ 20 тік арматура — накладка (L = 10d). **Анкеровка — шаблон 3.6 кестесі:** Ø12 600 · Ø14 700 · Ø16 800 · Ø18 850 · Ø20 950 · Ø22 1050 · Ø25 1200 · Ø28 1300 · Ø32 1500 | кесте салыстыру |")
    rep("| А12 |", "| А12 | Парақ аналог парағымен қатар қойылып салыстырылды (құрамы, атаулар, тізбектер) | көзбен (пилот) |\n| А13 | Стрелка: схемада колонна, стена, ригель маркасында жоқ; ригель маркасы ригель бойымен, сызықсыз. Стрелкалы выноска — стена проёмына: үстінде проём өлшемі, астында еденнен биіктігі (үлгі: Онкоцентр 2.x) | — |\n| А14 | Позиция выноскасы: үстінде «поз(ФØ)» (мыс. «1(Ф12)»), астында жалпы шаг («ш.200») — жоспарда да, элемент парағында да | мәтін тексеріс |")
    rep("| В1 |", "| В1 | Парақ — шаблон «Колонна Км-1» (Онкоцентрден алынған) көшірмесі, соз/қысқарт; өзің сызба. Пайдаланушының колонна ережелері түгел қолданылады | — |")
    rep("| В7 |", "| В7 | Колонна–ригель қиылысында әрдайым сетка (сейсмикада да), тұйық хомут қосылмайды | бар/жоқ |")
    rep("| Д1 |", "| Д1 | Парақ — шаблон «Ригель Рм-1» көшірмесі; пайдаланушының ригель ережелері түгел қолданылады; марка унификациясы паспорттағы шекпен | — |")
    rep("| Г4 |", "| Г4 | Скоба фасадта тік ножкамен; проём обрамлениесі шаблон 3.6 бойынша: хомут ш.100; 200, екі жағында 200×2, шетінен 50 | — |")
    return s
rw(os.path.join(OBS, "03_Армирование — қатаң чек-лист.md"), f03)
def f01(s):
    a = "| Анкеровка кестесі | | ереже / сұрақ |"; assert a in s
    s = s.replace(a, "| Анкеровка кестесі — әдепкі шаблон 3.6: Ø12 600 · Ø14 700 · Ø16 800 · Ø18 850 · Ø20 950 · Ø22 1050 · Ø25 1200 · Ø28 1300 · Ø32 1500 | | шаблон (12.11.2026) |")
    return s.replace("**Нахлёст: 71d (негізгі, Ø12 = 860) / 61d (Ø12 = 730)**", "**Нахлёст: 71d (негізгі, Ø12 = 860) / 61d (Ø12 = 730) / шаблон 3.6 кестесі (Ø12 = 700)**")
rw(os.path.join(OBS, "01_КЖ жобалау паспорты — үлгі.md"), f01)
def f05(s):
    a = "**Шешілді (12.11.2026, пайдаланушы):**"; assert a in s
    return s.replace(a, "**Шешілді (12.11.2026, екінші топ):** Қ-2 (стрелка), Қ-4/Қ-33 (анкеровка — шаблон 3.6 кестесі), Қ-7 (выноскада Ø жазылады), Қ-14 (колонна/ригель — шаблон), Н1 (түйінде әрдайым сетка) — `06` файлы, «Жауаптар» 3–7.\n\n" + a, 1)
rw(os.path.join(OBS, "05_Қайшылықтар, нормамен салыстыру, жетпейтін ережелер.md"), f05)
m = r"C:\Users\Admin\.claude\projects\D---------\memory"
for fn, add in (("leader-ticks-rule.md", "\n\n**НАҚТЫЛАУ 12.11.2026 (пайдаланушы):** схемада колонна, стена, ригель маркасында стрелка жоқ; ригель маркасы (Рм-1) ригель бойымен, выноска сызығынсыз. Стрелкалы выноска — стена проёмына (есік, терезе): үстінде проём өлшемі, астында еденнен биіктігі (үлгі: Онкоцентр схема каркаса). Позиция выноскасында диаметр ЖАЗЫЛАДЫ: «1(Ф12)» / астында шаг «ш.200» — жоспарда да.\n"),
                ("lap-table-61d.md", "\n\n**Шаблоннан (12.11.2026, `Шаблон для Кж.dwg` парақ 3.6):** анкеровка Ø12 600 · Ø14 700 · Ø16 800 · Ø18 850 · Ø20 950 · Ø22 1050 · Ø25 1200 · Ø28 1300 · Ø32 1500; шаблон нахлёст кестесі Ø12 700 · Ø14 900 · Ø16 1000 · Ø18 1200 (разбежка 300/400/500/600), Ø≥20 накладка L=10d (Н1 Ø20 200 … Н5 Ø32 320, С21-Рн); 71d: 860/1000/1140/1280/1420 (Ø12–20). Пайдаланушы ауызша анкеровкаға «61d көбіне, 55–56d» деді — шаблонмен сәйкес емес, жобада сұра.\n"),
                ("column-rules-template.md", "\n\n**12.11.2026 (пайдаланушы):** колонна мен ригель парағы әрдайым шаблон бойынша (шаблон Онкологиядан алынған); колонна–ригель қиылысында әрдайым сетка, сейсмикада да — тұйық хомут қосылмайды.\n")):
    p = os.path.join(m, fn); s = open(p, encoding="utf-8").read()
    if "12.11.2026" not in s.split("ТҮЗЕТУ 12.11.2026")[-1] or "Шаблоннан (12.11" not in s and fn.startswith("lap") or (not fn.startswith("lap") and add.strip()[:20] not in s):
        open(p, "w", encoding="utf-8", newline="\n").write(s.rstrip("\n") + add)
std = os.path.join(os.environ["LOCALAPPDATA"], "bekassyl-std", "_Стандарт_КЖ")
dst = os.path.join(std, "КЖ_жүйесі")
for f in os.listdir(OBS):
    sp = os.path.join(OBS, f)
    if os.path.isdir(sp): shutil.copytree(sp, os.path.join(dst, f), dirs_exist_ok=True)
    else: shutil.copyfile(sp, os.path.join(dst, f))
p = os.path.join(std, "ЕРЕЖЕЛЕР.md"); s = open(p, encoding="utf-8").read()
last = max(int(x) for x in re.findall(r"  - №(\d+) \(", s)); i = s.index("  - №%d (" % last); j = s.index("\n", i) + 1
items = [("анкеровка мен нахлёст кестелері шаблоннан", ANK + " " + LAPT + " " + L71 + " " + NAK + " " + PRO + " Көзі: " + TPL + ". Нахлёст үш нұсқа (71d негізгі, 61d, шаблон 3.6) — жоба басында сұралады."),
         ("стрелка", A4), ("выноскада диаметр", A5), ("колонна/ригель — шаблон", A6), ("түйінде сетка", A7)]
add = "".join("  - №%d (12.11, пайдаланушы — %s): %s\n" % (last + 1 + k, t, v) for k, (t, v) in enumerate(items))
open(p, "w", encoding="utf-8", newline="\n").write(s[:j] + add + s[j:])
print("ok", last + 1, last + len(items))
